import sys
import re

def update_poi_file(file_path, updates):
    with open(file_path, 'r', encoding='utf-8') as f:
        content = f.read()

    for poi_id, hu_desc, hu_facts in updates:
        # Find the POI block
        pattern = r'(id:\s*"' + re.escape(poi_id) + r'".*?descriptionAdvanced:\s*{.*?hu:\s*)"".*?(},.*?factsAdvanced:\s*{.*?hu:\s*)\[\]'
        
        def replace_func(match):
            return f'{match.group(1)}"{hu_desc}"{match.group(2)}{hu_facts}'

        new_content = re.sub(pattern, replace_func, content, flags=re.DOTALL)
        if new_content == content:
            print(f"Warning: Could not update POI {poi_id} in {file_path}. Pattern mismatch.")
        content = new_content

    with open(file_path, 'w', encoding='utf-8') as f:
        f.write(content)

